def move_num(s: str) -> str:
    letters = []
    numbers = []

    for ch in s:
        if ch.isdigit():
            numbers.append(ch)
        else:
            letters.append(ch)

    return ''.join(letters) + ''.join(numbers)


# Example usage and assertion
assert move_num('I1love143you55three3000thousand') == 'Iloveyouthreethousand1143553000'
